import java.io.*;
import java.util.*;

public class Variant4 {
  static PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

  int r, c;
  long[][] bin = new long[61][61];
  int[] countA = new int[61], countB = new int[61];
  long minDiff = Long.MAX_VALUE;
  String s;
  Map<Long, Long> table = new HashMap<>();

  public static void main(String[] args) {
    Variant4 app = new Variant4();
    app.execute();
    pw.flush();
  }

  static int parseInt() {
    int x = 0;
    boolean minus = false;
    try {
      boolean digitsStarted = false;
      for (int b = 0; (b = System.in.read()) != -1; ) {
        if (b == '-') {
          digitsStarted = true;
          minus = true;
          continue;
        } else if (b >= '0' && b <= '9') {
          digitsStarted = true;
          x = x * 10 + b - '0';
        } else if (digitsStarted) break;
      }
    } catch (IOException ignore) {}
    return minus ? -x : x;
  }

  static long parseLong() {
    long x = 0;
    boolean minus = false;
    try {
      boolean digitsStarted = false;
      for (int b = 0; (b = System.in.read()) != -1; ) {
        if (b == '-') {
          digitsStarted = true;
          minus = true;
          continue;
        } else if (b >= '0' && b <= '9') {
          digitsStarted = true;
          x = x * 10 + b - '0';
        } else if (digitsStarted) break;
      }
    } catch (IOException ignore) {}
    return minus ? -x : x;
  }

  static String parseString() {
    StringBuilder sb = new StringBuilder();
    try {
      boolean tokenStarted = false;
      for (int b = 0; (b = System.in.read()) != -1; ) {
        if (Character.isLetterOrDigit(b) || b == '?') {
          tokenStarted = true;
          sb.append((char) b);
        } else if (tokenStarted) break;
      }
    } catch (IOException ignore) {}
    return sb.toString();
  }

  static int parseChars(char[] buf, int offset) {
    int len = 0;
    try {
      boolean tokenStarted = false;
      for (int b = 0; (b = System.in.read()) != -1; ) {
        if (Character.isLetterOrDigit(b)) {
          tokenStarted = true;
          buf[offset + len++] = (char) b;
        } else if (tokenStarted) break;
      }
    } catch (IOException ignore) {}
    return len;
  }

  void explore(long left, long right, int i, int j) {
    long diff = Math.abs(left - right);
    if (minDiff <= 1 || diff - bin[i][r] * bin[j][r] >= minDiff) return;
    if (i == r - 1 && j == r - 1) {
      if (diff < minDiff) minDiff = diff;
      return;
    }
    if (i >= r) {
      long diff1 = bin[i][r] - bin[i - 1][r];
      long factor = bin[j][r];
      explore(left, right + diff1 * factor, i - 1, j);
    }
    if (j >= r) {
      long diff2 = bin[j][r] - bin[j - 1][r];
      long factor = bin[i][r];
      explore(left + diff2 * factor, right, i, j - 1);
    }
  }

  long compute(long left, long right, int i, int j) {
    long diff = Math.abs(left - right);
    if (diff - bin[i][r] * bin[j][r] > minDiff) return 0L;
    long key = (left << 7) | (i << 4) | j;
    Long stored = table.get(key);
    if (stored != null) return stored;
    if (i < r || j < r) {
      if (i >= countA[i + j] && j >= countB[i + j]) {
        int total = i + j;
        i -= countA[total];
        j -= countB[total];
        return bin[i + j][i];
      }
      return 0L;
    }
    long ways = 0L;
    char ch = s.charAt(i + j - 1);
    if (ch != 'B') {
      long diff1 = bin[i][r] - bin[i - 1][r];
      long factor = bin[j][r];
      ways += compute(left, right + diff1 * factor, i - 1, j);
    }
    if (ch != 'A') {
      long diff2 = bin[j][r] - bin[j - 1][r];
      long factor = bin[i][r];
      ways += compute(left + diff2 * factor, right, i, j - 1);
    }
    table.put(key, ways);
    return ways;
  }

  void execute() {
    r = parseInt();
    c = parseLong() == 0 ? (int)parseLong() : parseInt();
    for (int i = 0; i <= 2 * (r + c); i++) {
      for (int j = 0; j <= i; j++) {
        if (j == 0 || j == i) bin[i][j] = 1;
        else bin[i][j] = bin[i - 1][j - 1] + bin[i - 1][j];
      }
    }
    long left = 0, right = 0;
    int p = r + c, q = r + c;
    while (p >= r && q >= r) {
      if (left > right) {
        long diff1 = bin[p][r] - bin[p - 1][r];
        long factor = bin[q][r];
        right += diff1 * factor;
        p--;
      } else {
        long diff2 = bin[q][r] - bin[q - 1][r];
        long factor = bin[p][r];
        left += diff2 * factor;
        q--;
      }
    }
    minDiff = Math.abs(left - right);
    explore(0, 0, r + c, r + c);
    s = parseString();
    for (int i = 0; i < 2 * (r + c); i++) {
      countA[i + 1] = countA[i] + (s.charAt(i) == 'A' ? 1 : 0);
      countB[i + 1] = countB[i] + (s.charAt(i) == 'B' ? 1 : 0);
    }
    long ans = compute(0, 0, r + c, r + c);
    pw.println(ans);
  }
}
